from __future__ import annotations

import uuid
from datetime import datetime
from typing import Annotated, Literal

from pydantic import AfterValidator, Field

from app.schemas import ApiModel
from app.text import clean_text

BODY_MAX = 2000


def _body(v: str) -> str:
    text = clean_text(v, max_lines=60)
    if not text:
        raise ValueError("write a message")
    if len(text) > BODY_MAX:
        raise ValueError(f"messages are at most {BODY_MAX} characters")
    return text


class MessageIn(ApiModel):
    # Generated by the app once per message and reused on every retry (idempotency).
    client_message_id: uuid.UUID
    body: Annotated[str, Field(min_length=1, max_length=BODY_MAX + 100), AfterValidator(_body)]


class MessageOut(ApiModel):
    id: uuid.UUID
    n: int = Field(description="Sequence number within the conversation (1, 2, 3, ...)")
    from_me: bool
    body: str
    sent_at: datetime
    client_message_id: uuid.UUID | None = Field(description="Only on my own messages")
    safety_tip: Literal["money"] | None = Field(
        description="On messages from them that mention money or payments: show a safety tip"
    )


class MessagePage(ApiModel):
    items: list[MessageOut] = Field(description="Oldest first")
    has_more: bool = Field(description="More messages exist in the direction asked for")


class ReadIn(ApiModel):
    up_to_n: int = Field(ge=0, description="The latest message number the member has seen")


class ReadOut(ApiModel):
    last_read_n: int
    unread: int


class NudgeTermsOut(ApiModel):
    version: str
    hurtful: list[str] = Field(description="Ask the sender to confirm before sending")
    money: list[str] = Field(description="Show the recipient a safety tip")
